mapper.select:
SELECT id, service_type_id AS serviceTypeId, item_type AS itemType,
       pricing_mode AS pricingMode, weight_min AS weightMin, weight_max AS weightMax,
       price, destination_id AS destinationId, created_at AS createdAt
FROM ups_shipping_rate
WHERE service_type_id = #{serviceTypeId}
  AND item_type = #{itemType}
  AND destination_id = #{destinationId}
  AND weight_min <= #{weight}
ORDER BY weight_min
